class Splitter {
    public static String split(String s) {
        String front = "";
        String back = "";
        for (int i = 0; i < s.length(); i++) {
            String ch = s.substring(i, i + 1);
            if ("aeiou".indexOf(ch) >= 0) {
                front += ch;
            } else {
                back += ch;
            }
        }
        return front + "-" + back;
    }
}
