class Roster {
    private int[] ids;
    public Roster(int[] start) { ids = start; }
    public int[] getIds() { return ids; }
    public int total() {
        int sum = 0;
        for (int v : ids) {
            sum += v;
        }
        return sum;
    }
}

public class Client {
    public static void main(String[] args) {
        int[] data = { 6, 3, 7 };
        Roster r = new Roster(data);
        data[0] = 0;
        int[] got = r.getIds();
        got[1] = 0;
        System.out.println(r.total());
    }
}
